-- [시나리오 A] 고객사 변경요청 (요청번호는 트리거 자동 채번, BR-16~23 검증 통과) --------
INSERT INTO change_request (cr_id, project_id, contact_id, received_by_emp_id, request_date, title, content, reason) VALUES
  (1, 47, 20, 3, '2026-04-02', '통계 대시보드 화면 추가', '상담 이력을 일·주·월 단위로 보여 주는 관리자용 통계 대시보드 화면 3종을 추가해 달라는 요청', '운영 부서가 상담 품질 지표를 매주 확인해야 함'),
  (2, 47, 20, 3, '2026-04-11', '관리자 권한 세분화', '관리자 계정을 상담 관리자와 운영 관리자로 나누고 메뉴 접근 권한을 분리해 달라는 요청', '고객사 내부 보안 감사 지적 사항'),
  (3, 48, 1, 53, '2026-05-10', '외부 결제(PG) 연동 추가', '온라인 결제 대행사(PG) 연동과 결제 취소·환불 화면을 추가해 달라는 요청', '유료 서비스 출시 일정이 앞당겨짐'),
  (4, 49, 5, 69, '2026-06-30', '보고서 PDF 출력 기능', '조회 화면의 결과를 PDF 보고서로 내려받는 기능 추가 요청', '임원 보고용 자료 작성 시간 단축'),
  (5, 50, 5, 18, '2026-06-29', '영문(다국어) 화면 지원', '전체 화면을 영문으로도 제공해 달라는 요청', '해외 지사 사용자 추가'),
  (6, 51, 21, 65, '2026-07-13', '모바일 반응형 화면 적용', '현장 직원이 휴대폰으로 조회할 수 있도록 주요 화면을 반응형으로 바꿔 달라는 요청', '현장 점검 업무의 모바일 전환'),
  (7, 52, 13, 47, '2026-08-21', '데이터 이관 범위 확대', '기존 시스템 데이터 이관 범위를 최근 5년에서 최근 10년으로 늘려 달라는 요청', '과거 이력 조회 수요'),
  (8, 53, 21, 45, '2026-08-09', '실시간 알림 기능 추가', '결재 요청이 오면 메신저와 이메일로 즉시 알림을 보내는 기능 추가 요청', '결재 지연 민원 증가');
