  (3, 3, 1, 53, '2027-05-07', 12000000, 'PG 사 인증 일정 포함 3주 소요, 보안 점검 필요', '2026-05-13 10:00:00', 'APPROVED', 2, '2026-05-17', '매출 영향이 커서 우선 승인', 'PENDING', NULL, NULL, NULL, NULL),
  (4, 4, 1, 69, '2027-02-21', 2000000, '출력 템플릿 5종 개발 1주', '2026-07-03 10:00:00', 'REJECTED', 1, '2026-07-07', '기존 계약의 ''조회 결과 출력'' 범위에 포함되어 추가 비용 없이 기존 일정 안에서 처리', 'PENDING', NULL, NULL, NULL, NULL),
  (5, 5, 1, 18, '2027-06-23', 8000000, '전 화면 문구 분리와 번역 검수 포함 20일', '2026-07-02 10:00:00', 'APPROVED', 1, '2026-07-06', '해외 지사 확대 계획과 일치', 'AGREED', 7, '2026-07-10', '주간 회의록 (고객사 서명)', 18),
  (6, 5, 2, 18, '2027-06-13', 4000000, '고객이 범위를 주요 화면 12개로 축소 → 재검토, 10일·400만 원', '2026-07-18 10:00:00', 'PENDING', NULL, NULL, NULL, 'PENDING', NULL, NULL, NULL, NULL),
  (7, 7, 1, 47, '2027-07-08', 15000000, '이관 대상 4배 증가, 정합성 검증 2주 추가', '2026-08-24 10:00:00', 'APPROVED', 2, '2026-08-28', '필요성은 인정, 비용은 고객 부담 조건', 'DECLINED', 14, '2026-09-01', '고객사 예산 부족으로 거절 (전화 확인 후 이메일 회신)', 47),
