INSERT INTO development_plan (plan_id, emp_id, project_id, course_id, manager_emp_id, improvement_goal, reason, created_date, due_date) VALUES
  (1, 32, 46, 4, 84, 'SQL 튜닝 실무 역량 향상', '물류센터 자동화 연계 시스템 평가에서 업무수행 평균 2.0점. 담당 기술 영역의 산출물 재작업 의견이 있음', '2026-06-30', '2027-02-25'),
  (2, 35, 21, 2, 84, '보고서 작성과 보고 역량 향상', '인사 평가 시스템 고도화 평가에서 커뮤니케이션 평균 2.2점. 평가 의견에 요구사항 확인·전달 보완 필요 의견이 있음', '2026-03-11', '2026-11-06'),
