  (5, 71, 15, 1, 84, '고객 요구사항 확인·전달 역량 향상', '결제 대행(PG) 연동 고도화 평가에서 커뮤니케이션 평균 2.7점. 평가 의견에 요구사항 확인·전달 보완 필요 의견이 있음', '2026-04-07', '2026-12-03'),
  (6, 48, 41, 2, 84, '보고서 작성과 보고 역량 향상', '커넥티드카 백엔드 플랫폼 구축 평가에서 커뮤니케이션 평균 2.7점. 평가 의견에 요구사항 확인·전달 보완 필요 의견이 있음', '2026-06-30', '2027-02-25'),
  (7, 14, 13, 8, 84, '일정·위험 관리 역량 향상', '병원 예약 모바일 앱 개발 평가에서 업무수행 평균 2.8점. 담당 기술 영역의 산출물 재작업 의견이 있음', '2026-04-25', '2026-12-21'),
  (8, 29, 38, 8, 84, '일정·위험 관리 역량 향상', '차세대 계정계 시스템 구축 평가에서 업무수행 평균 3.0점. 담당 기술 영역의 산출물 재작업 의견이 있음', '2026-05-04', '2026-12-30'),
  (9, 39, 4, 3, 84, 'Spring Boot 실무 역량 향상', '대출 심사 시스템 고도화 평가에서 업무수행 평균 3.0점. 담당 기술 영역의 산출물 재작업 의견이 있음', '2026-05-13', '2027-01-08'),
  (10, 47, 5, 5, 84, 'React 실무 역량 향상', '민원 포털 고도화 평가에서 업무수행 평균 3.0점. 담당 기술 영역의 산출물 재작업 의견이 있음', '2026-05-22', '2027-01-17'),
  (11, 22, 7, 8, 84, '일정·위험 관리 역량 향상', '회원 통합 인증(SSO) 구축 평가에서 업무수행 평균 3.0점. 담당 기술 영역의 산출물 재작업 의견이 있음', '2026-05-31', '2027-01-26'),
  (12, 34, 1, 7, 84, 'TDD 실무 역량 향상', '통합 검색 엔진 구축 평가에서 업무수행 평균 3.0점. 담당 기술 영역의 산출물 재작업 의견이 있음', '2026-06-09', '2027-02-04'),
  (13, 63, 20, 8, 84, '일정·위험 관리 역량 향상', '제조 설비 예지보전 시스템 평가에서 업무수행 평균 3.0점. 담당 기술 영역의 산출물 재작업 의견이 있음', '2026-06-18', '2027-02-13'),
  (14, 31, 22, 8, 84, '일정·위험 관리 역량 향상', '택배 기사 앱 개발 평가에서 업무수행 평균 3.0점. 담당 기술 영역의 산출물 재작업 의견이 있음', '2026-06-27', '2027-02-22'),
  (15, 4, 45, 1, 84, '고객 요구사항 확인·전달 역량 향상', '고객 상담 이력 분석 시스템 고객 평가에서 요구사항 확인 과정의 보완 필요 의견이 있음. 평가 점수만으로 판단하지 않고 의견 내용을 근거로 추천', '2026-10-05', '2027-02-28');
